package com.harsh.explore.examples;import com.harsh.explore.data.Student;import com.harsh.explore.data.StudentDb;import java.util.HashMap;import java.util.List;import java.util.Map;import java.util.function.BiFunction;import java.util.function.Predicate;public class BiFunctionExample {    static BiFunction<List<Student>, Predicate<Student>, Map<String,Double>> studentBiFuction=            ((students, studentPredicate)-> {                HashMap<String, Double> studentGradeMap = new HashMap<>();                students.forEach(student->{                    if(studentPredicate.test(student)){                    studentGradeMap.put(student.getName(), student.getGpa());                }});                return studentGradeMap;    });    public static void main(String[] args) {        System.out.println(studentBiFuction.apply(StudentDb.getAllStudents(), PredicateAndConsumerExample.p1));    }}